//! Cross-language vectors generated by the predecessor implementation's Python
//! reference and frozen here: the hash framing, the
//! gate-set digests and semantics, the codec and the checker's verdict on
//! real batches must all agree byte for byte.

use serde::Deserialize;
use veritor_zk_common::{
    check_any, check_batch, check_batch_multi, check_openings, check_openings_multi, domain_id,
    empty_root, framed_hash, gate_set, leaf, node, parse_any_witness, parse_multiproof_witness,
    parse_statement, parse_witness, sha256, tagged_sha256, uint, uint_len, AnyWitness, CheckError,
    GateSet,
};

#[derive(Deserialize)]
struct Vectors {
    framing: Vec<Framing>,
    uint: Vec<Uint>,
    tagged_sha256: Vec<Tagged>,
    domains: Vec<Domain>,
    gate_sets: Vec<GateSetVector>,
    batches: Vec<Batch>,
}

#[derive(Deserialize)]
struct Framing {
    tag: String,
    parts: Vec<String>,
    digest: String,
}

#[derive(Deserialize)]
struct Uint {
    value: u64,
    bytes: String,
}

#[derive(Deserialize)]
struct Tagged {
    tag: String,
    payload: String,
    digest: String,
}

#[derive(Deserialize)]
struct Leaf {
    rank: u64,
    position: u64,
    schema: String,
    value: String,
    digest: String,
}

#[derive(Deserialize)]
struct Node {
    level: u64,
    index: u64,
    left: String,
    right: String,
    digest: String,
}

#[derive(Deserialize)]
struct Domain {
    owner: i64,
    binding: String,
    identity: String,
    count: u64,
    domain_id: String,
    leaf: Leaf,
    node: Node,
    empty_root: String,
    root: String,
}

#[derive(Deserialize)]
struct Evaluation {
    op: String,
    args: Vec<u64>,
    out: u64,
}

#[derive(Deserialize)]
struct GateSetVector {
    id: String,
    width: u32,
    manifest: String,
    digest: String,
    evaluations: Vec<Evaluation>,
}

#[derive(Deserialize)]
struct Rejected {
    name: String,
    witness: String,
}

#[derive(Deserialize)]
struct Batch {
    name: String,
    statement: String,
    witness: String,
    multiproof_witness: String,
    statement_digest: String,
    obligations: usize,
    kinds: usize,
    gate_set_id: String,
    width: u32,
    ops: Vec<String>,
    verdict: bool,
    rejected_witnesses: Vec<Rejected>,
    rejected_multiproof_witnesses: Vec<Rejected>,
}

/// Whether this is a DIAGNOSTIC build: authentication tests then assert the skip instead.
const UNSOUND: bool = veritor_zk_common::UNSOUND;

fn load() -> Vectors {
    let data = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors.json"))
        .expect("tests/vectors.json (a frozen fixture; nothing in this repository regenerates it)");
    serde_json::from_str(&data).expect("vectors.json parses")
}

fn unhex(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "odd hex length");
    (0..text.len())
        .step_by(2)
        .map(|at| u8::from_str_radix(&text[at..at + 2], 16).expect("hex"))
        .collect()
}

fn digest32(text: &str) -> [u8; 32] {
    unhex(text).try_into().expect("32-byte digest")
}

#[test]
fn framing_matches_merkle_py() {
    for case in load().framing {
        let parts: Vec<Vec<u8>> = case.parts.iter().map(|part| unhex(part)).collect();
        let refs: Vec<&[u8]> = parts.iter().map(Vec::as_slice).collect();
        assert_eq!(
            framed_hash(&unhex(&case.tag), &refs),
            digest32(&case.digest),
            "tag {}",
            case.tag
        );
    }
}

#[test]
fn uint_matches_merkle_py() {
    for case in load().uint {
        let bytes = uint(case.value);
        assert_eq!(
            &bytes[8 - uint_len(case.value)..],
            unhex(&case.bytes).as_slice(),
            "uint({})",
            case.value
        );
    }
}

#[test]
fn tagged_sha256_matches_identity_py() {
    for case in load().tagged_sha256 {
        assert_eq!(
            tagged_sha256(case.tag.as_bytes(), &unhex(&case.payload)),
            digest32(&case.digest),
            "tag {}",
            case.tag
        );
    }
}

#[test]
fn domains_leaves_and_nodes_match_commitment_domain() {
    for case in load().domains {
        let binding = digest32(&case.binding);
        let identity = digest32(&case.identity);
        let id = domain_id(&binding, (case.owner + 2) as u64, &identity, case.count);
        assert_eq!(
            id,
            digest32(&case.domain_id),
            "domain of owner {}",
            case.owner
        );
        assert_eq!(
            leaf(
                &id,
                case.leaf.rank,
                case.leaf.position,
                case.leaf.schema.as_bytes(),
                &unhex(&case.leaf.value)
            ),
            digest32(&case.leaf.digest),
            "leaf of owner {}",
            case.owner
        );
        assert_eq!(
            node(
                &id,
                case.node.level,
                case.node.index,
                &digest32(&case.node.left),
                &digest32(&case.node.right)
            ),
            digest32(&case.node.digest),
            "node of owner {}",
            case.owner
        );
        assert_eq!(
            empty_root(&id),
            digest32(&case.empty_root),
            "empty root of owner {}",
            case.owner
        );
        if case.count == 0 {
            assert_eq!(
                empty_root(&id),
                digest32(&case.root),
                "an empty domain's root is its empty root"
            );
        }
    }
}

#[test]
fn gate_sets_match_core_gates_py() {
    let vectors = load();
    assert!(vectors
        .gate_sets
        .iter()
        .any(|case| case.id == "veritor.int8-q7@1"));
    for case in vectors.gate_sets {
        let set = GateSet::resolve(&case.id, case.width)
            .unwrap_or_else(|| panic!("unknown gate set {}", case.id));
        assert_eq!(set.manifest(), case.manifest, "manifest of {}", case.id);
        assert_eq!(
            set.digest(),
            digest32(&case.digest),
            "digest of {}",
            case.id
        );
        assert!(
            !case.evaluations.is_empty(),
            "{} has evaluation vectors",
            case.id
        );
        for evaluation in case.evaluations {
            let op = set
                .op(&evaluation.op)
                .unwrap_or_else(|| panic!("{} lacks {}", case.id, evaluation.op));
            assert_eq!(
                set.evaluate(op, &evaluation.args),
                Some(evaluation.out),
                "{}({:?}) at width {}",
                evaluation.op,
                evaluation.args,
                case.width
            );
        }
    }
}

#[test]
fn real_batches_parse_and_check() {
    let vectors = load();
    assert!(vectors
        .batches
        .iter()
        .any(|batch| batch.gate_set_id == "veritor.int8-q7@1"));
    for batch in vectors.batches {
        let statement_bytes = unhex(&batch.statement);
        assert_eq!(
            sha256(&statement_bytes),
            digest32(&batch.statement_digest),
            "{}",
            batch.name
        );
        let statement = parse_statement(&statement_bytes).expect("statement parses");
        assert_eq!(
            statement.obligations.len(),
            batch.obligations,
            "{}",
            batch.name
        );
        assert_eq!(statement.kinds.len(), batch.kinds, "{}", batch.name);
        assert_eq!(statement.gate_set_id, batch.gate_set_id, "{}", batch.name);
        assert_eq!(statement.width, batch.width, "{}", batch.name);
        // every op the Python side says the batch exercises occurs in some kind program
        let mut ops: Vec<String> = statement
            .kinds
            .iter()
            .flat_map(|kind| kind.gates.iter().map(|gate| gate.op.clone()))
            .collect();
        ops.sort();
        ops.dedup();
        assert_eq!(ops, batch.ops, "{} exercises these ops", batch.name);
        let witness = parse_witness(&unhex(&batch.witness)).expect("witness parses");
        // every batch's openings authenticate; a batch with verdict `false` is one whose
        // prover committed a wrong value, so the rejection must come from the relation pass
        let set = gate_set(&statement).expect("known gate set");
        let decoded = check_openings(&statement, &witness, &set).expect("openings authenticate");
        match check_batch(&statement, &witness) {
            Ok(()) => assert!(batch.verdict, "{} must be rejected", batch.name),
            Err(error) => {
                assert!(!batch.verdict, "{} must be accepted: {error}", batch.name);
                assert!(
                    matches!(error, CheckError::Relation { .. }),
                    "{}: {error}",
                    batch.name
                );
            }
        }
        // the format-2 witness of the same openings decodes to the very same values
        let multiproof_bytes = unhex(&batch.multiproof_witness);
        assert!(
            multiproof_bytes.len() < unhex(&batch.witness).len() / 10,
            "{}",
            batch.name
        );
        let multiproof =
            parse_multiproof_witness(&multiproof_bytes).expect("multiproof witness parses");
        let decoded_multi =
            check_openings_multi(&statement, &multiproof, &set).expect("multiproof authenticates");
        assert_eq!(
            decoded_multi, decoded,
            "{}: both formats decode alike",
            batch.name
        );
        assert_eq!(
            check_batch_multi(&statement, &multiproof).is_ok(),
            batch.verdict,
            "{}: format-2 verdict",
            batch.name
        );
        // and the guest's dispatch reaches the same verdict for either encoding
        for bytes in [unhex(&batch.witness), multiproof_bytes] {
            let any = parse_any_witness(&bytes).expect("either format parses");
            assert_eq!(
                matches!(any, AnyWitness::Multiproof(_)),
                bytes.starts_with(veritor_zk_common::MULTIPROOF_WITNESS_MAGIC)
            );
            assert_eq!(
                check_any(&statement, &any).is_ok(),
                batch.verdict,
                "{}",
                batch.name
            );
        }
    }
}

/// Tampering that only the authentication pass detects.  A DIAGNOSTIC build does
/// not run it, so there the same witnesses must be *accepted* (the skip is real).
fn authentication_only(batch: &Batch, rejected: &Rejected) -> bool {
    match rejected.name.as_str() {
        "broken-path" | "corrupted-sibling" | "extra-sibling" | "missing-sibling" => true,
        // the flipped value of an honest batch is caught by the relation pass unless it
        // is a pinned input or lands on a satisfiable value; only the path proves it
        "flipped-value" => batch.verdict,
        _ => false,
    }
}

#[test]
fn tampered_witnesses_are_rejected() {
    for batch in load().batches {
        let statement = parse_statement(&unhex(&batch.statement)).expect("statement parses");
        for rejected in &batch.rejected_witnesses {
            let outcome: Result<(), CheckError> = match parse_witness(&unhex(&rejected.witness)) {
                Err(_) => Err(CheckError::WitnessShape("unparseable".into())),
                Ok(witness) => check_batch(&statement, &witness),
            };
            if UNSOUND && rejected.name == "broken-path" {
                // the skip is real: only the relation pass can still reject
                assert_eq!(
                    outcome.is_ok(),
                    batch.verdict,
                    "{}: the diagnostic build skips the path",
                    batch.name
                );
            } else if !UNSOUND || !authentication_only(&batch, rejected) {
                assert!(
                    outcome.is_err(),
                    "{}: {} must be rejected",
                    batch.name,
                    rejected.name
                );
            }
        }
        for rejected in &batch.rejected_multiproof_witnesses {
            let outcome: Result<(), CheckError> =
                match parse_multiproof_witness(&unhex(&rejected.witness)) {
                    Err(_) => Err(CheckError::WitnessShape("unparseable".into())),
                    Ok(witness) => check_batch_multi(&statement, &witness),
                };
            if UNSOUND && rejected.name == "corrupted-sibling" {
                assert_eq!(
                    outcome.is_ok(),
                    batch.verdict,
                    "{}: the diagnostic build skips the multiproof",
                    batch.name
                );
            } else if !UNSOUND || !authentication_only(&batch, rejected) {
                assert!(
                    outcome.is_err(),
                    "{}: {} must be rejected",
                    batch.name,
                    rejected.name
                );
            }
        }
    }
}

#[test]
fn the_verdict_byte_tells_a_diagnostic_build_apart() {
    use veritor_zk_common::{decode_verdict, public_values, DIAGNOSTIC_BANNER};
    let digest = [9u8; 32];
    let accept = public_values(&digest, true);
    let reject = public_values(&digest, false);
    assert_eq!(&accept[..32], &digest);
    assert_eq!(decode_verdict(accept[32]), Some((true, UNSOUND)));
    assert_eq!(decode_verdict(reject[32]), Some((false, UNSOUND)));
    assert_eq!(accept[32] == 1, !UNSOUND, "only a sound build commits 1");
    assert_eq!(DIAGNOSTIC_BANNER.is_some(), UNSOUND);
    assert_eq!(decode_verdict(2), None);
}

#[test]
fn statement_bytes_are_canonical_for_the_parser() {
    // A trailing byte, a truncated tail and a wrong magic are all rejected.
    for batch in load().batches {
        let statement_bytes = unhex(&batch.statement);
        let mut trailing = statement_bytes.clone();
        trailing.push(0);
        assert!(parse_statement(&trailing).is_err());
        assert!(parse_statement(&statement_bytes[..statement_bytes.len() - 1]).is_err());
        let mut magic = statement_bytes.clone();
        magic[0] ^= 1;
        assert!(parse_statement(&magic).is_err());
    }
}
